import fs from 'node:fs';
import path from 'node:path';
import { loadEnv, telegramBotToken } from './src/config.mjs';
import { storePaths } from './src/store.mjs';

const env = await loadEnv();
const token = telegramBotToken(env);
const ALEX = '6644482344';
const FF = '-1003868178598';
const root = storePaths().dir;

function tailJsonl(p, n=80) {
  if (!fs.existsSync(p)) return [];
  const lines = fs.readFileSync(p,'utf8').split(/\r?\n/).filter(Boolean);
  return lines.slice(-n).map(l => { try { return JSON.parse(l); } catch { return {raw:l.slice(0,200)}; }});
}

function showMsg(label, m) {
  const when = m.at || m.ts || m.date || m.receivedAt || '';
  const who = m.authorName || m.from?.username || m.from?.id || m.authorId || m.role || '?';
  const chat = m.chatId || m.channelId || m.chat?.id || '';
  const id = m.messageId || m.id || m.msgId || m.update_id || '';
  let text = m.text || m.content || m.caption || m.question || m.body || '';
  if (!text && m.message) text = m.message.text || m.message.caption || '';
  console.log('---', label, '|', when, '|', who, '| chat', chat, '| id', id);
  console.log(String(text).replace(/\s+/g,' ').trim().slice(0,500));
}

console.log('=== STORE ROOT', root);
console.log('=== inbound.jsonl (telegram-ish last 60)');
const inbound = tailJsonl(path.join(root,'logs','inbound.jsonl'), 120)
  .filter(x => {
    const s = JSON.stringify(x).toLowerCase();
    return s.includes('telegram') || s.includes(ALEX) || s.includes(FF) || s.includes('tg:');
  });
console.log('hits', inbound.length);
for (const m of inbound.slice(-40)) showMsg('in', m);

console.log('\n=== FF vault inbound');
const ffIn = tailJsonl(path.join(root,'telegram','groups',FF,'inbound.jsonl'), 50);
console.log('n', ffIn.length);
for (const m of ffIn.slice(-25)) showMsg('ff', m);

console.log('\n=== FF memory');
for (const m of tailJsonl(path.join(root,'telegram','groups',FF,'memory.jsonl'), 20).slice(-15)) showMsg('mem', m);

console.log('\n=== turns telegram');
const turns = tailJsonl(path.join(root,'conversations','turns.jsonl'), 200)
  .filter(t => String(t.surface||'').includes('telegram') || String(t.channelId||'').includes(ALEX) || String(t.channelId||'').includes(FF) || String(t.channelId||'').includes('tg:'));
console.log('n', turns.length);
for (const t of turns.slice(-25)) {
  console.log('--- turn', t.at||t.ts, '|', t.authorName||t.authorId, '| ch', t.channelId);
  console.log('Q:', String(t.question||'').replace(/\s+/g,' ').slice(0,350));
  console.log('A:', String(t.answer||'').replace(/\s+/g,' ').slice(0,350));
}

console.log('\n=== utterances telegram-ish');
const uttPath = path.join(root,'training','utterances.jsonl');
const utts = tailJsonl(uttPath, 300).filter(u => {
  const s = JSON.stringify(u).toLowerCase();
  return s.includes('telegram') || s.includes(ALEX) || s.includes(FF) || s.includes('tg:');
});
console.log('path exists', fs.existsSync(uttPath), 'hits', utts.length);
for (const u of utts.slice(-20)) {
  console.log('--- utt', u.at||u.ts||u.when, '|', u.surface||u.channel||'', '|', (u.text||u.content||u.utterance||'').toString().replace(/\s+/g,' ').slice(0,300));
}

console.log('\n=== getUpdates (offset=-1 peek only via limit)');
// Use offset=-1 to get only latest without consuming backlog? Telegram: negative offset retrieves from end.
const r = await fetch('https://api.telegram.org/bot'+token+'/getUpdates?limit=50&timeout=0');
const data = await r.json();
console.log('ok', data.ok, 'n', (data.result||[]).length, data.description||'');
if (data.description) console.log('desc', data.description);
const byChat = {};
for (const u of data.result||[]) {
  const m = u.message || u.edited_message || u.channel_post || u.my_chat_member || u.callback_query?.message;
  const chatId = String(m?.chat?.id || u.my_chat_member?.chat?.id || '?');
  byChat[chatId] = (byChat[chatId]||0)+1;
  const text = m?.text || m?.caption || (u.my_chat_member ? '[my_chat_member '+u.my_chat_member.new_chat_member?.status+']' : '') || JSON.stringify(u).slice(0,120);
  const when = m?.date ? new Date(m.date*1000).toISOString() : '';
  const who = m?.from?.username || m?.from?.id || '?';
  console.log('upd', u.update_id, when, 'chat', chatId, 'from', who, 'mid', m?.message_id, ':', String(text).replace(/\s+/g,' ').slice(0,280));
}
console.log('byChat', byChat);
"

